var ModelVideosGet = &command.Spec{
	Group:          "model",
	Name:           "videos get",
	Summary:        "Get HeyGen Video",
	Description:    "Get a HeyGen Video generation in the caller's workspace. Status is pending, processing, completed, failed, or cancelled. Completed results include a fresh video_url, duration, aspect_ratio, dimensions, and seed when available. Failed and cancelled results include failure_code and failure_message. Poll again to refresh an expired download URL. Missing videos and videos from another workspace return the same 404.",
	ResponseSchema: "{\n  \"properties\": {\n    \"data\": {\n      \"properties\": {\n        \"aspect_ratio\": {\n          \"description\": \"Output aspect ratio. Adaptive outputs report the actual width:height ratio after pixel alignment.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"created_at\": {\n          \"description\": \"Request creation time as Unix seconds.\",\n          \"type\": \"integer\"\n        },\n        \"duration\": {\n          \"description\": \"Generated video duration in seconds, present when completed.\",\n          \"nullable\": true,\n          \"type\": \"integer\"\n        },\n        \"failure_code\": {\n          \"description\": \"Failure code, present when failed or cancelled.\",\n          \"enum\": [\n            \"generation_failed\",\n            \"generation_cancelled\"\n          ],\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"failure_message\": {\n          \"description\": \"Failure explanation, present when failed or cancelled.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"height\": {\n          \"description\": \"Actual output height in pixels, present when reported by the renderer.\",\n          \"nullable\": true,\n          \"type\": \"integer\"\n        },\n        \"model\": {\n          \"description\": \"Requested video generation model.\",\n          \"enum\": [\n            \"heygen-video-1\"\n          ],\n          \"type\": \"string\"\n        },\n        \"seed\": {\n          \"description\": \"Generation seed, present when completed.\",\n          \"nullable\": true,\n          \"type\": \"integer\"\n        },\n        \"status\": {\n          \"description\": \"Current generation status.\",\n          \"enum\": [\n            \"pending\",\n            \"processing\",\n            \"completed\",\n            \"failed\",\n            \"cancelled\"\n          ],\n          \"type\": \"string\"\n        },\n        \"timings\": {\n          \"description\": \"Generation timing in seconds, when reported by the renderer.\",\n          \"nullable\": true,\n          \"properties\": {\n            \"inference\": {\n              \"description\": \"Diffusion transformer execution time in seconds. Excludes other inference stages, encoding, and queueing.\",\n              \"type\": \"number\"\n            }\n          },\n          \"required\": [\n            \"inference\"\n          ],\n          \"type\": \"object\"\n        },\n        \"video_id\": {\n          \"description\": \"Generated video identifier.\",\n          \"type\": \"string\"\n        },\n        \"video_url\": {\n          \"description\": \"Download URL, present when completed. Poll again to obtain a fresh URL.\",\n          \"nullable\": true,\n          \"type\": \"string\"\n        },\n        \"width\": {\n          \"description\": \"Actual output width in pixels, present when reported by the renderer.\",\n          \"nullable\": true,\n          \"type\": \"integer\"\n        }\n      },\n      \"required\": [\n        \"video_id\",\n        \"status\",\n        \"model\",\n        \"created_at\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"required\": [],\n  \"type\": \"object\"\n}",
	Endpoint:       "/v3/models/videos/{video_id}",
	Method:         "GET",
	BodyEncoding:   "",
	Examples: []string{
		"# Poll an Instant Video until completed, failed, or cancelled\n  heygen model videos get <video-id>",
	},
	Args: []command.ArgSpec{
		{Name: "video-id", Param: "video_id", Help: ""},
	},
}
